args.content:
import { cookies, headers } from 'next/headers'

export default async function ThemeLanguageDisplay() {
  const cookieStore = await cookies()
  const theme = cookieStore.get('theme')?.value ?? 'light'

  const headersList = await headers()
  const acceptLanguage = headersList.get('accept-language') ?? 'Not set'

  const primaryLanguage = acceptLanguage !== 'Not set'
    ? acceptLanguage.split(',')[0].split(';')[0].trim()
    : 'Not set'

  return (
    <div>
      <p>
        <strong>Theme:</strong> {theme}
      </p>
      <p>
        <strong>Preferred Language:</strong> {primaryLanguage}
      </p>
    </div>
  )
}

